<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard · LedgerFlow</title><link rel="stylesheet" href="assets/app.css"></head><body><aside class="sidebar"><div class="brand">Ledger<span>Flow</span></div><nav><a class="active" href="index.php">Dashboard</a><a href="transactions.php">Transactions</a><?php if(in_array(Auth::user()['role'],['admin','accountant'],true)): ?><a href="customers.php">Customers</a><a href="funding_sources.php">Funding Sources</a><?php endif; ?><a href="reports.php">Reports</a><a href="api_docs.php">API Docs</a></nav><div class="side-bottom"><span><?=e(Auth::user()['name'])?></span><a href="logout.php">Sign out</a></div></aside><main class="main"><header><div><p class="eyebrow">CONTROL CENTER</p><h1>Financial overview</h1><p class="muted">Monitor posted activity and ledger health.</p></div><a class="btn primary" href="transactions.php?new=1">+ New transaction</a></header><?php if($success): ?><div class="alert success"><?=e($success)?></div><?php endif; ?><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><section class="cards"><div class="card"><span>Total posted volume</span><strong><?=money($stats['total_posted'])?></strong></div><div class="card"><span>Posted transactions</span><strong><?=number_format($stats['transaction_count'])?></strong></div><div class="card"><span>Active customers</span><strong><?=number_format($stats['customers'])?></strong></div><div class="card"><span>Funding sources</span><strong><?=number_format($stats['funding_sources'])?></strong></div></section><section class="panel"><div class="panel-head"><div><h2>Recent transactions</h2><p class="muted">Latest ledger activity</p></div><a href="transactions.php">View all</a></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Type</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach(array_slice($rows,0,10)